/** 合并日文说明（prog_library_ja.js） */
const withJa = (text, ja) => (text && ja ? { ...text, ja } : text);
export const ENTRIES = RAW_ENTRIES.map((e) => {
  const ja = ENTRY_JA[e.id] || {};
  return {
    ...e,
    theory: withJa(e.theory, ja.theory),
    ...(e.limits ? { limits: withJa(e.limits, ja.limits) } : {}),
    ...(e.variantOf ? { variantOf: { ...e.variantOf, how: withJa(e.variantOf.how, ja.how) } } : {}),
    ...(e.original ? { original: { ...e.original, ...(e.original.note ? { note: withJa(e.original.note, ja.note) } : {}) } } : {}),
  };
});
